/**
 * FILE: concept_9_financial_peace_mind.js
 * THEME: Finance & Investment — Financial Peace of Mind & Smart Investor Mindset
 * STYLE: Modern Flat Vector with Solid Chroma Green Screen (#00FF00)
 * ASPECT RATIO: 16:9 | RESOLUTION READY: FHD / 2K / 4K (Ultra HD)
 * DURATION: 20 Seconds Seamless Loop | SCENES: 1
 * TARGET EXPORT BITRATE: 100 Mbps (Uncompressed Crisp Vector Edges, Zero Glow/Bloom)
 */

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const s = minSide / 1080;
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Fundamental harmonic phases for 100% seamless 20-second loop
  const tau = Math.PI * 2;
  const p1 = sceneProgress * tau + currentScene * 0;
  const p2 = sceneProgress * tau * 2;
  const p3 = sceneProgress * tau * 3;
  const p4 = sceneProgress * tau * 4;

  // Color Palette (Crisp Commercial Flat Vector, Zero Glow/Bloom)
  const COL = {
    greenScreen: '#00FF00',
    outline: '#162035',
    surfaceWhite: '#FFFFFF',
    surfaceLight: '#F1F5F9',
    surfaceMuted: '#CBD5E1',
    slateDark: '#334155',
    slateMid: '#64748B',
    brainPinkLight: '#FCE7F3',
    brainPink: '#F48FB1',
    brainPinkMid: '#EC407A',
    brainPinkDark: '#D81B60',
    goldLight: '#FEF08A',
    goldMid: '#FACC15',
    goldDark: '#EAB308',
    goldDeep: '#CA8A04',
    emeraldLight: '#A7F3D0',
    emeraldMid: '#22C55E',
    emeraldDark: '#15803D',
    cyanLight: '#BAE6FD',
    cyanMid: '#38BDF8',
    cyanDark: '#0284C7',
    purpleMid: '#A855F7',
    orangeMid: '#FB923C'
  };

  const strokeW = 5.5 * s;
  const thinStrokeW = 3.5 * s;

  ctx.save();
  ctx.shadowBlur = 0;
  ctx.shadowColor = 'transparent';
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  // 1. SOLID GREEN SCREEN BACKGROUND
  ctx.fillStyle = COL.greenScreen;
  ctx.fillRect(0, 0, width, height);

  // Helper: Rounded Rectangle Path
  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function fillAndStroke(fillColor, outlineColor, lineWidth) {
    if (fillColor) {
      ctx.fillStyle = fillColor;
      ctx.fill();
    }
    if (outlineColor && lineWidth > 0) {
      ctx.strokeStyle = outlineColor;
      ctx.lineWidth = lineWidth;
      ctx.stroke();
    }
  }

  // Helper: Crisp Vector Dollar Emblem
  function drawVectorDollar(centerX, centerY, scaleSize, color, lineW) {
    const w = 13 * scaleSize;
    const h = 20 * scaleSize;
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.beginPath();
    ctx.moveTo(centerX + w * 0.75, centerY - h * 0.45);
    ctx.bezierCurveTo(
      centerX + w * 0.75, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.35
    );
    ctx.bezierCurveTo(
      centerX - w * 0.85, centerY + h * 0.02,
      centerX + w * 0.85, centerY - h * 0.02,
      centerX + w * 0.85, centerY + h * 0.40
    );
    ctx.bezierCurveTo(
      centerX + w * 0.85, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.45
    );
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(centerX, centerY - h * 0.98);
    ctx.lineTo(centerX, centerY + h * 0.98);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Vector Upward Arrow
  function drawUpArrow(centerX, centerY, size, color, lineW) {
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.beginPath();
    ctx.moveTo(centerX, centerY + size * 0.7);
    ctx.lineTo(centerX, centerY - size * 0.65);
    ctx.moveTo(centerX - size * 0.55, centerY - size * 0.1);
    ctx.lineTo(centerX, centerY - size * 0.7);
    ctx.lineTo(centerX + size * 0.55, centerY - size * 0.1);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Gold Coin Medallion
  function drawGoldMedallion(centerX, centerY, radius, dollarScale) {
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius, 0, tau);
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    ctx.beginPath();
    ctx.arc(centerX, centerY, radius * 0.74, 0, tau);
    fillAndStroke(COL.goldLight, COL.outline, 2.5 * s);

    drawVectorDollar(centerX, centerY, dollarScale, COL.outline, 3.2 * s);
  }

  // Helper: Side-View Stacked Coin Cylinder
  function drawCoinCylinder(centerX, topY, coinW, coinH) {
    roundedRectPath(centerX - coinW * 0.5, topY, coinW, coinH, 7 * s);
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    roundedRectPath(centerX - coinW * 0.40, topY + 4 * s, coinW * 0.20, coinH - 8 * s, 3.5 * s);
    fillAndStroke(COL.goldLight, null, 0);

    roundedRectPath(centerX + coinW * 0.20, topY + 4 * s, coinW * 0.20, coinH - 8 * s, 3.5 * s);
    fillAndStroke(COL.goldDeep, null, 0);

    roundedRectPath(centerX - coinW * 0.5, topY, coinW, coinH, 7 * s);
    fillAndStroke(null, COL.outline, thinStrokeW);
  }

  // Helper: Gold Bullion Bar Trapezoid
  function drawBullionBar(centerX, bottomY, barW, barH) {
    const topW = barW * 0.80;
    ctx.beginPath();
    ctx.moveTo(centerX - barW * 0.5, bottomY);
    ctx.lineTo(centerX - topW * 0.5, bottomY - barH);
    ctx.lineTo(centerX + topW * 0.5, bottomY - barH);
    ctx.lineTo(centerX + barW * 0.5, bottomY);
    ctx.closePath();
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    ctx.beginPath();
    ctx.moveTo(centerX - topW * 0.38, bottomY - barH + 6 * s);
    ctx.lineTo(centerX + topW * 0.38, bottomY - barH + 6 * s);
    ctx.lineTo(centerX + topW * 0.42, bottomY - 6 * s);
    ctx.lineTo(centerX - topW * 0.42, bottomY - 6 * s);
    ctx.closePath();
    fillAndStroke(COL.goldLight, null, 0);
  }

  // =========================================================================
  // 2. STRUCTURAL BASELINE PLATFORM & NON-INTERSECTING ZEN BRIDGES
  // =========================================================================
  const baseLineY = cy + 395 * s;

  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = strokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 735 * s, baseLineY);
  ctx.lineTo(cx + 735 * s, baseLineY);
  ctx.stroke();

  // Outer baseline accent ticks
  const tickShift = Math.sin(p2) * 6 * s;
  ctx.beginPath();
  ctx.moveTo(cx - 810 * s - tickShift, baseLineY);
  ctx.lineTo(cx - 760 * s - tickShift, baseLineY);
  ctx.moveTo(cx + 760 * s + tickShift, baseLineY);
  ctx.lineTo(cx + 810 * s + tickShift, baseLineY);
  ctx.stroke();

  // Sub-platform line
  ctx.beginPath();
  ctx.moveTo(cx - 360 * s, baseLineY + 18 * s);
  ctx.lineTo(cx + 360 * s, baseLineY + 18 * s);
  ctx.stroke();

  // Dedicated Horizontal Zen Bridges in Lower Corridor (y = cy + 205*s)
  const bridgeY = cy + 205 * s;
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = thinStrokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 282 * s, bridgeY);
  ctx.lineTo(cx - 224 * s, bridgeY);
  ctx.moveTo(cx + 224 * s, bridgeY);
  ctx.lineTo(cx + 282 * s, bridgeY);
  ctx.stroke();

  const bProgL = (sceneProgress * 4) % 1;
  ctx.beginPath();
  ctx.arc(cx - 276 * s + bProgL * 46 * s, bridgeY, 6 * s, 0, tau);
  fillAndStroke(COL.emeraldMid, COL.outline, 2.5 * s);

  const bProgR = (sceneProgress * 4 + 0.5) % 1;
  ctx.beginPath();
  ctx.arc(cx + 230 * s + bProgR * 46 * s, bridgeY, 6 * s, 0, tau);
  fillAndStroke(COL.goldMid, COL.outline, 2.5 * s);

  // =========================================================================
  // 3. LEFT-TOP ZONE: MENTAL CLARITY & FINANCIAL PEACE CARD
  // Bounding Box: x in [cx - 685*s, cx - 295*s], y in [cy - 360*s, cy - 35*s]
  // =========================================================================
  const ltFloatY = Math.sin(p2) * 4.5 * s;
  const ltX = cx - 685 * s;
  const ltY = cy - 360 * s + ltFloatY;
  const ltW = 390 * s;
  const ltH = 315 * s;

  roundedRectPath(ltX, ltY, ltW, ltH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Top Header Strip inside Left-Top Card
  roundedRectPath(ltX + 18 * s, ltY + 18 * s, ltW - 36 * s, 46 * s, 12 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, thinStrokeW);

  const headerDots = [COL.emeraldMid, COL.cyanMid, COL.goldMid];
  for (let d = 0; d < 3; d++) {
    ctx.beginPath();
    ctx.arc(ltX + 40 * s + d * 24 * s, ltY + 41 * s, 7 * s, 0, tau);
    fillAndStroke(headerDots[d], COL.outline, 2.5 * s);
  }

  roundedRectPath(ltX + 118 * s, ltY + 35 * s, 150 * s, 12 * s, 6 * s);
  fillAndStroke(COL.slateDark, null, 0);

  roundedRectPath(ltX + ltW - 102 * s, ltY + 27 * s, 68 * s, 28 * s, 8 * s);
  fillAndStroke(COL.emeraldMid, COL.outline, 2.5 * s);

  // Inner Chart Frame (y: ltY + 80*s, height: 215*s)
  const cFrameX = ltX + 18 * s;
  const cFrameY = ltY + 80 * s;
  const cFrameW = ltW - 36 * s;
  const cFrameH = 215 * s;

  roundedRectPath(cFrameX, cFrameY, cFrameW, cFrameH, 14 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, thinStrokeW);

  // Horizontal Grid Lines
  ctx.strokeStyle = COL.surfaceMuted;
  ctx.lineWidth = 2 * s;
  for (let g = 1; g <= 3; g++) {
    const gy = cFrameY + (cFrameH / 4) * g;
    ctx.beginPath();
    ctx.moveTo(cFrameX + 16 * s, gy);
    ctx.lineTo(cFrameX + cFrameW - 16 * s, gy);
    ctx.stroke();
  }

  // 5 Calm Zen Stability Bars + Separated Stable Equilibrium Line
  const barCount = 5;
  const barW = 32 * s;
  const barSpacing = (cFrameW - 76 * s) / (barCount - 1);
  const barBottomY = cFrameY + cFrameH - 14 * s;
  const baseZenRatios = [0.45, 0.48, 0.52, 0.55, 0.58];
  const zenNodes = [];

  for (let i = 0; i < barCount; i++) {
    const bCenterX = cFrameX + 38 * s + i * barSpacing;
    const mod = 0.02 * Math.sin(p2 - i * 0.6);
    const bh = (baseZenRatios[i] + mod) * (cFrameH - 52 * s);
    const by = barBottomY - bh;

    const barCol = i === 4 ? COL.goldMid : (i >= 2 ? COL.emeraldMid : COL.cyanMid);
    roundedRectPath(bCenterX - barW * 0.5, by, barW, bh, 7 * s);
    fillAndStroke(barCol, COL.outline, thinStrokeW);

    zenNodes.push({ x: bCenterX, y: by - 26 * s });
  }

  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = 4 * s;
  ctx.beginPath();
  for (let i = 0; i < zenNodes.length; i++) {
    if (i === 0) ctx.moveTo(zenNodes[i].x, zenNodes[i].y);
    else ctx.lineTo(zenNodes[i].x, zenNodes[i].y);
  }
  ctx.stroke();

  for (let i = 0; i < zenNodes.length; i++) {
    ctx.beginPath();
    ctx.arc(zenNodes[i].x, zenNodes[i].y, 7 * s, 0, tau);
    fillAndStroke(i === 4 ? COL.goldMid : COL.surfaceWhite, COL.outline, 2.8 * s);
  }

  // =========================================================================
  // 4. LEFT-BOTTOM ZONE: STRESS-FREE METRICS & GOLD RESERVES PEDESTAL
  // Bounding Box: x in [cx - 685*s, cx - 295*s], y in [cy + 25*s, cy + 395*s]
  // =========================================================================
  const lbFloatY = Math.cos(p2) * 4 * s;
  const lbX = cx - 685 * s;
  const lbY = cy + 25 * s + lbFloatY;
  const lbW = 390 * s;
  const lbCardH = 190 * s;

  // 4A. Upper Stress-Free Metrics Card
  roundedRectPath(lbX, lbY, lbW, lbCardH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  const zenKpiCols = [COL.emeraldMid, COL.goldMid, COL.cyanMid];
  for (let sr = 0; sr < 3; sr++) {
    const ry = lbY + 22 * s + sr * 54 * s;
    roundedRectPath(lbX + 18 * s, ry, lbW - 36 * s, 42 * s, 10 * s);
    fillAndStroke(COL.surfaceLight, COL.outline, 2.8 * s);

    roundedRectPath(lbX + 26 * s, ry + 7 * s, 72 * s, 28 * s, 7 * s);
    fillAndStroke(zenKpiCols[sr], COL.outline, 2.5 * s);

    const trackX = rbTrackX(lbX);
    const trackW = 185 * s;
    roundedRectPath(trackX, ry + 14 * s, trackW, 14 * s, 7 * s);
    fillAndStroke(COL.surfaceWhite, COL.outline, 2.2 * s);

    const fillW = (0.58 + 0.30 * Math.sin(p2 - sr * 1.1)) * (trackW - 6 * s);
    roundedRectPath(trackX + 3 * s, ry + 17 * s, fillW, 8 * s, 4 * s);
    fillAndStroke(zenKpiCols[sr], null, 0);

    ctx.beginPath();
    ctx.arc(lbX + lbW - 42 * s, ry + 21 * s, 8 * s, 0, tau);
    fillAndStroke(sr === 0 ? COL.emeraldMid : COL.goldMid, COL.outline, 2.5 * s);
  }
  function rbTrackX(x) { return x + 114 * s; }

  // 4B. Lower Gold Bullion & Coin Pedestal on baseLineY
  const pedLX = lbX;
  const pedLW = lbW;
  const pedLH = 24 * s;
  const pedLY = baseLineY - pedLH;

  roundedRectPath(pedLX, pedLY, pedLW, pedLH, 8 * s);
  fillAndStroke(COL.slateDark, COL.outline, strokeW);

  // Column 1 (Left): 2 Stacked Gold Bullion Bars (x center = lbX + 84*s, spans [22, 146])
  const bulCX = lbX + 84 * s;
  drawBullionBar(bulCX, pedLY, 124 * s, 38 * s);
  drawBullionBar(bulCX, pedLY - 38 * s, 108 * s, 36 * s);

  // Column 2 (Middle): 4 Stacked Gold Coins (x center = lbX + 216*s, spans [174, 258], 28*s clear gap!)
  const stackLCX = lbX + 216 * s;
  const cH = 24 * s;
  for (let c = 0; c < 4; c++) {
    drawCoinCylinder(stackLCX, pedLY - (c + 1) * cH, 84 * s, cH);
  }

  // Column 3 (Right): Front Gold Dollar Medallion on Stand (x center = lbX + 330*s, spans [286, 374], 28*s clear gap!)
  const medLCX = lbX + 330 * s;
  const medLCY = pedLY - 64 * s + Math.sin(p2) * 4 * s;
  roundedRectPath(medLCX - 22 * s, pedLY - 16 * s, 44 * s, 16 * s, 5 * s);
  fillAndStroke(COL.goldDeep, COL.outline, thinStrokeW);
  drawGoldMedallion(medLCX, medLCY, 44 * s, 1.25 * s);

  // =========================================================================
  // 5. CENTER ZONE: PROPORTIONAL & STRUCTURED MEDITATING BRAIN + SATELLITES
  // Directly modelled after the reference video (01:18 - 01:23):
  // - Multi-lobed cloud brain silhouette with internal gyri folds
  // - Outstretched meditation arms with Gyan Mudra (OK-pinch) hands
  // - Properly crossed lotus legs resting above a gold bullion cushion
  // - Non-overlapping satellite badges in dedicated outer corner stations
  // =========================================================================
  const brainFloatY = Math.sin(p2) * 5.5 * s;
  const brainCX = cx;
  const brainCY = cy - 15 * s + brainFloatY;

  // 5A. Central Zen Pedestal & Gold Bullion Cushion on baseLineY (y: cy + 280*s to cy + 395*s)
  roundedRectPath(cx - 156 * s, baseLineY - 36 * s, 312 * s, 36 * s, 12 * s);
  fillAndStroke(COL.slateDark, COL.outline, strokeW);

  roundedRectPath(cx - 108 * s, baseLineY - 21 * s, 216 * s, 8 * s, 4 * s);
  fillAndStroke(COL.goldMid, null, 0);

  // Gold Bullion Cushion Stack resting on Central Pedestal (Strictly below meditating brain)
  const cushionBaseY = baseLineY - 36 * s;
  drawBullionBar(cx - 66 * s, cushionBaseY, 122 * s, 34 * s);
  drawBullionBar(cx + 66 * s, cushionBaseY, 122 * s, 34 * s);
  drawBullionBar(cx, cushionBaseY - 34 * s, 148 * s, 34 * s);

  // 5B. Structured Meditating Brain Character
  ctx.save();
  ctx.translate(brainCX, brainCY);

  // --- 1. Crossed Lotus Legs (Structured left & right thighs crossing cleanly at center) ---
  // Left thigh & tucked foot
  ctx.save();
  ctx.translate(-32 * s, 96 * s);
  ctx.rotate(-0.20);
  roundedRectPath(-42 * s, -15 * s, 88 * s, 30 * s, 15 * s);
  fillAndStroke(COL.brainPinkMid, COL.outline, strokeW);
  ctx.restore();

  // Right thigh crossing over in front (creates authentic lotus posture like 01:20)
  ctx.save();
  ctx.translate(32 * s, 96 * s);
  ctx.rotate(0.20);
  roundedRectPath(-46 * s, -15 * s, 88 * s, 30 * s, 15 * s);
  fillAndStroke(COL.brainPink, COL.outline, strokeW);
  ctx.restore();

  // Left & Right Lotus Knee/Foot Caps
  ctx.beginPath();
  ctx.arc(-68 * s, 88 * s, 14 * s, 0, tau);
  fillAndStroke(COL.brainPink, COL.outline, strokeW);

  ctx.beginPath();
  ctx.arc(68 * s, 88 * s, 14 * s, 0, tau);
  fillAndStroke(COL.brainPink, COL.outline, strokeW);

  // --- 2. Outstretched Meditation Arms & Gyan Mudra Hands (Matches reference 01:18 - 01:23) ---
  const armSway = Math.sin(p4) * 2.5 * s;

  // Left Arm curving from lower-left lobe out to Left Mudra Hand at (-142*s, +36*s)
  const lHandX = -142 * s;
  const lHandY = 36 * s + armSway;

  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = 22 * s;
  ctx.beginPath();
  ctx.moveTo(-88 * s, 32 * s);
  ctx.quadraticCurveTo(-116 * s, 54 * s, lHandX + 12 * s, lHandY + 4 * s);
  ctx.stroke();

  ctx.strokeStyle = COL.brainPink;
  ctx.lineWidth = 11 * s;
  ctx.beginPath();
  ctx.moveTo(-88 * s, 32 * s);
  ctx.quadraticCurveTo(-116 * s, 54 * s, lHandX + 12 * s, lHandY + 4 * s);
  ctx.stroke();

  // Left Gyan Mudra Hand (Pinched thumb-index circle + 2 delicate fingers)
  ctx.beginPath();
  ctx.arc(lHandX, lHandY, 15 * s, 0, tau);
  fillAndStroke(COL.brainPink, COL.outline, thinStrokeW);
  ctx.beginPath();
  ctx.arc(lHandX - 2 * s, lHandY - 2 * s, 5.5 * s, 0, tau);
  fillAndStroke(COL.greenScreen, COL.outline, 2.8 * s);

  // Left Mudra outer finger ticks
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = 4 * s;
  ctx.beginPath();
  ctx.moveTo(lHandX - 11 * s, lHandY - 10 * s);
  ctx.lineTo(lHandX - 20 * s, lHandY - 18 * s);
  ctx.moveTo(lHandX - 14 * s, lHandY - 2 * s);
  ctx.lineTo(lHandX - 24 * s, lHandY - 5 * s);
  ctx.stroke();

  // Right Arm curving from lower-right lobe out to Right Mudra Hand at (+142*s, +36*s)
  const rHandX = 142 * s;
  const rHandY = 36 * s + armSway;

  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = 22 * s;
  ctx.beginPath();
  ctx.moveTo(88 * s, 32 * s);
  ctx.quadraticCurveTo(116 * s, 54 * s, rHandX - 12 * s, rHandY + 4 * s);
  ctx.stroke();

  ctx.strokeStyle = COL.brainPink;
  ctx.lineWidth = 11 * s;
  ctx.beginPath();
  ctx.moveTo(88 * s, 32 * s);
  ctx.quadraticCurveTo(116 * s, 54 * s, rHandX - 12 * s, rHandY + 4 * s);
  ctx.stroke();

  // Right Gyan Mudra Hand
  ctx.beginPath();
  ctx.arc(rHandX, rHandY, 15 * s, 0, tau);
  fillAndStroke(COL.brainPink, COL.outline, thinStrokeW);
  ctx.beginPath();
  ctx.arc(rHandX + 2 * s, rHandY - 2 * s, 5.5 * s, 0, tau);
  fillAndStroke(COL.greenScreen, COL.outline, 2.8 * s);

  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = 4 * s;
  ctx.beginPath();
  ctx.moveTo(rHandX + 11 * s, rHandY - 10 * s);
  ctx.lineTo(rHandX + 20 * s, rHandY - 18 * s);
  ctx.moveTo(rHandX + 14 * s, rHandY - 2 * s);
  ctx.lineTo(rHandX + 24 * s, rHandY - 5 * s);
  ctx.stroke();

  // --- 3. Multi-Lobed Cloud Brain Silhouette (Two-Pass Fill & Stroke for Unified Scalloped Outline) ---
  const brainLobes = [
    { x: -38, y: -56, r: 46 }, // Top-left frontal lobe
    { x:  38, y: -56, r: 46 }, // Top-right frontal lobe
    { x: -82, y: -16, r: 44 }, // Mid-left temporal lobe
    { x:  82, y: -16, r: 44 }, // Mid-right temporal lobe
    { x: -64, y:  34, r: 42 }, // Lower-left lobe
    { x:  64, y:  34, r: 42 }, // Lower-right lobe
    { x: -24, y:  44, r: 38 }, // Base-left lobe
    { x:  24, y:  44, r: 38 }, // Base-right lobe
    { x:   0, y:  -8, r: 64 }  // Central core mass
  ];

  // Pass 1: Draw Outer Bold Outline around all Brain Lobes
  ctx.fillStyle = COL.outline;
  for (let i = 0; i < brainLobes.length; i++) {
    const lb = brainLobes[i];
    ctx.beginPath();
    ctx.arc(lb.x * s, lb.y * s, lb.r * s + strokeW, 0, tau);
    ctx.fill();
  }

  // Pass 2: Draw Smooth Pink Interior Fill across all Brain Lobes
  ctx.fillStyle = COL.brainPink;
  for (let i = 0; i < brainLobes.length; i++) {
    const lb = brainLobes[i];
    ctx.beginPath();
    ctx.arc(lb.x * s, lb.y * s, lb.r * s, 0, tau);
    ctx.fill();
  }

  // Top-left soft highlight arcs inside frontal lobes
  ctx.strokeStyle = COL.brainPinkLight;
  ctx.lineWidth = 6 * s;
